\set ON_ERROR_STOP on

BEGIN;

SET LOCAL lock_timeout = '15s';

SET LOCAL standard_conforming_strings = on;

CREATE SCHEMA IF NOT EXISTS evaluation;

CREATE TABLE IF NOT EXISTS evaluation.runs (
  run_id text PRIMARY KEY,
  source text NOT NULL,
  run_at timestamptz,
  commit_sha text,
  suite text,
  suite_version text,
  suite_sha256 text,
  corpus_sha256 text,
  embedding_provider text,
  embedding_alias text,
  retrieval jsonb,
  generation_model text,
  prompt_sha256 text,
  synthetic boolean NOT NULL,
  generation_model_id text,
  generation_provider text,
  generation_quantization text,
  gateway_config_sha256 text,
  is_real boolean NOT NULL,
  non_real_reasons text[] NOT NULL,
  comparability_key text NOT NULL,
  format text NOT NULL,
  milestone boolean NOT NULL,
  report_path text,
  report_sha256 text NOT NULL
);

ALTER TABLE evaluation.runs ADD COLUMN IF NOT EXISTS generation_model_id text;
ALTER TABLE evaluation.runs ADD COLUMN IF NOT EXISTS generation_provider text;
ALTER TABLE evaluation.runs ADD COLUMN IF NOT EXISTS generation_quantization text;
ALTER TABLE evaluation.runs ADD COLUMN IF NOT EXISTS gateway_config_sha256 text;

CREATE TABLE IF NOT EXISTS evaluation.results (
  run_id text NOT NULL REFERENCES evaluation.runs (run_id) ON DELETE CASCADE,
  measure_type text NOT NULL CHECK (measure_type IN ('A', 'B')),
  grp text NOT NULL,
  metric_id text NOT NULL,
  behavior text NOT NULL,
  status text NOT NULL CHECK (status IN ('pass', 'fail', 'blocked', 'not_run', 'measured', 'not_measured')),
  case_count bigint,
  value double precision,
  unit text NOT NULL,
  numerator double precision,
  denominator bigint,
  ci_low double precision,
  ci_high double precision,
  judgment text CHECK (judgment IS NULL OR judgment IN ('automatic', 'human')),
  selected boolean NOT NULL DEFAULT false,
  PRIMARY KEY (run_id, grp, metric_id, behavior, status),
  CHECK (status <> 'not_measured' OR (value IS NULL AND numerator IS NULL AND case_count IS NULL
    AND ci_low IS NULL AND ci_high IS NULL)),
  CHECK (status <> 'measured' OR value IS NOT NULL)
);

CREATE OR REPLACE VIEW evaluation.config_changes AS
WITH ordered AS (
  SELECT
    run_id,
    source,
    run_at,
    suite_version,
    suite_sha256,
    generation_model,
    generation_model_id,
    generation_provider,
    generation_quantization,
    gateway_config_sha256,
    identity_registered,
    prompt_sha256,
    corpus_sha256,
    lag(run_id) OVER w AS previous_run_id,
    lag(suite_version) OVER w AS previous_suite_version,
    lag(suite_sha256) OVER w AS previous_suite_sha256,
    lag(generation_model) OVER w AS previous_generation_model,
    lag(generation_model_id) OVER w AS previous_generation_model_id,
    lag(generation_provider) OVER w AS previous_generation_provider,
    lag(generation_quantization) OVER w AS previous_generation_quantization,
    lag(gateway_config_sha256) OVER w AS previous_gateway_config_sha256,
    lag(identity_registered) OVER w AS previous_identity_registered,
    lag(prompt_sha256) OVER w AS previous_prompt_sha256,
    lag(corpus_sha256) OVER w AS previous_corpus_sha256
  FROM (
    SELECT
      runs.*,
      (generation_model_id IS NOT NULL OR generation_provider IS NOT NULL OR generation_quantization IS NOT NULL
        OR gateway_config_sha256 IS NOT NULL) AS identity_registered
    FROM evaluation.runs
  ) AS runs
  WHERE run_at IS NOT NULL
  WINDOW w AS (PARTITION BY source ORDER BY run_at, run_id)
),
detected AS (
  SELECT
    run_id,
    previous_run_id,
    source,
    run_at,
    array_remove(ARRAY[
      CASE WHEN suite_version IS DISTINCT FROM previous_suite_version
             OR suite_sha256 IS DISTINCT FROM previous_suite_sha256 THEN 'bateria'::text END,
      CASE WHEN generation_model IS DISTINCT FROM previous_generation_model THEN 'modelo'::text END,
      CASE WHEN identity_registered <> previous_identity_registered
             THEN 'identidad del modelo no registrada en una de las dos'::text END,
      CASE WHEN identity_registered AND previous_identity_registered
             AND generation_model_id IS DISTINCT FROM previous_generation_model_id THEN 'identificador de modelo'::text END,
      CASE WHEN identity_registered AND previous_identity_registered
             AND generation_provider IS DISTINCT FROM previous_generation_provider THEN 'proveedor del modelo'::text END,
      CASE WHEN identity_registered AND previous_identity_registered
             AND generation_quantization IS DISTINCT FROM previous_generation_quantization THEN 'cuantizacion'::text END,
      CASE WHEN identity_registered AND previous_identity_registered
             AND gateway_config_sha256 IS DISTINCT FROM previous_gateway_config_sha256 THEN 'configuracion del gateway'::text END,
      CASE WHEN prompt_sha256 IS NOT NULL AND previous_prompt_sha256 IS NOT NULL
             AND prompt_sha256 <> previous_prompt_sha256 THEN 'prompt'::text END,
      CASE WHEN corpus_sha256 IS DISTINCT FROM previous_corpus_sha256 THEN 'corpus'::text END
    ], NULL) AS changes
  FROM ordered
  WHERE previous_run_id IS NOT NULL
)
SELECT
  run_id,
  previous_run_id,
  source,
  run_at,
  changes,
  'Cambia: ' || array_to_string(changes, ', ') AS annotation
FROM detected
WHERE cardinality(changes) > 0;

CREATE OR REPLACE VIEW evaluation.comparable_runs AS
SELECT
  comparability_key,
  run_id,
  source,
  run_at,
  is_real,
  milestone,
  series_runs
FROM (
  SELECT
    comparability_key,
    run_id,
    source,
    run_at,
    is_real,
    milestone,
    count(*) OVER (PARTITION BY comparability_key) AS series_runs
  FROM evaluation.runs
  WHERE run_at IS NOT NULL
) AS dated
WHERE series_runs >= 2;

LOCK TABLE evaluation.runs, evaluation.results IN ACCESS EXCLUSIVE MODE;

CREATE TEMP TABLE handoff_incoming_runs (LIKE evaluation.runs INCLUDING DEFAULTS) ON COMMIT DROP;

CREATE TEMP TABLE handoff_incoming_results (LIKE evaluation.results INCLUDING DEFAULTS) ON COMMIT DROP;






DO $check$
BEGIN
  IF (SELECT count(*) FROM handoff_incoming_runs) <> 19 OR
     (SELECT count(*) FROM handoff_incoming_results) <> 1688 THEN
    RAISE EXCEPTION 'El paquete de evaluacion no coincide con el manifiesto';
  END IF;
  IF EXISTS (
    SELECT 1 FROM evaluation.runs e JOIN handoff_incoming_runs i USING(run_id)
    WHERE to_jsonb(e) IS DISTINCT FROM to_jsonb(i)
  ) THEN
    RAISE EXCEPTION 'Una ejecucion existente tiene la misma identidad y otros metadatos: no sobrescribir';
  END IF;
  IF EXISTS (
    (SELECT e.* FROM evaluation.results e JOIN handoff_incoming_runs i USING(run_id)
     EXCEPT ALL
     SELECT i.* FROM handoff_incoming_results i JOIN evaluation.runs e USING(run_id))
    UNION ALL
    (SELECT i.* FROM handoff_incoming_results i JOIN evaluation.runs e USING(run_id)
     EXCEPT ALL
     SELECT e.* FROM evaluation.results e JOIN handoff_incoming_runs i USING(run_id))
  ) THEN
    RAISE EXCEPTION 'Los resultados de una ejecucion existente difieren: no sobrescribir';
  END IF;
END
$check$;
CREATE TEMP TABLE handoff_missing_ids ON COMMIT DROP AS
  SELECT run_id FROM handoff_incoming_runs i
  WHERE NOT EXISTS (SELECT 1 FROM evaluation.runs e WHERE e.run_id=i.run_id);
  SELECT i.* FROM handoff_incoming_runs i JOIN handoff_missing_ids m USING(run_id);
  SELECT i.* FROM handoff_incoming_results i JOIN handoff_missing_ids m USING(run_id);
SELECT (SELECT count(*) FROM handoff_missing_ids) AS ejecuciones_anadidas,
       (SELECT count(*) FROM handoff_incoming_results r JOIN handoff_missing_ids m USING(run_id)) AS resultados_anadidos,
       (SELECT count(*) FROM evaluation.runs) AS ejecuciones_totales,
       (SELECT count(*) FROM evaluation.results) AS resultados_totales;
COMMIT;
